//! The Lambda wire formats (ADR 0005, X3) against the golden fixture `compat/fixtures/lambda.json`.
//!
//! Extension fixtures are generated by the Rust implementation (ADR 0005, Mitigations): a Go port
//! of these helpers writes code until it gives the same answers on these records. Regenerate after
//! an intentional change:
//!
//! ```sh
//! EVT_UPDATE_FIXTURES=1 cargo test -p photon-evt-lambda --all-features --test fixtures
//! ```

use std::path::PathBuf;

use photon_evt::journal::{Scope, counter_view, row_sk, row_view};
use photon_evt::wire::dynamo::{
    AttributeValue, Item, event_item, head_item, snapshot_item, view_row_item,
};
use photon_evt::{
    BoxError, EntityId, EventSequence, EventVersion, Metadata, SerializedEvent, SerializedSnapshot,
};
use photon_evt_lambda::{
    BatchResponse, DecodeError, EventFilter, EventName, JournalFilter, JournalWakeup, StreamEvent,
    StreamRecord, StreamViewType, StreamedEvent, decode_event, decode_wakeup, process_events,
    process_wakeups,
};
use serde_json::{Value, json};

fn fixture_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../compat/fixtures/lambda.json")
}

fn scope(name: &str) -> Scope {
    Scope::new(name).unwrap()
}

fn event(entity_id: &str, sequence: i64, event_type: &str) -> SerializedEvent {
    let mut metadata = Metadata::default()
        .with_timestamp("2026-10-20T00:00:00Z")
        .with_command_id("cmd-0001");
    metadata.region = "us-west-2".into();
    metadata.commit_id = "01JDXK7Q3W9B5N2M8P4R6TAVHY".into();

    SerializedEvent {
        id: format!("{entity_id}:{sequence}").into(),
        sequence: EventSequence(sequence),
        event_type: event_type.into(),
        version: EventVersion(1),
        entity_id: entity_id.into(),
        entity_type: "account".into(),
        payload: br#"{"amount":5}"#.to_vec(),
        metadata,
    }
}

fn keys_of(item: &Item) -> Item {
    item.iter()
        .filter(|(name, _)| *name == "pk" || *name == "sk")
        .map(|(name, value)| (name.clone(), value.clone()))
        .collect()
}

fn record(name: EventName, item: Item, sequence: &str, view_type: StreamViewType) -> StreamRecord {
    let mut record = StreamRecord::new(name, keys_of(&item), sequence);
    record.event_id = format!("record-{sequence}");
    record.aws_region = "us-west-2".into();
    record.event_source_arn =
        "arn:aws:dynamodb:us-west-2:000000000000:table/evt-local/stream/2026-10-20T00:00:00.000"
            .into();
    record.change.approximate_creation_date_time = Some(1_792_454_400.0);
    record.change.stream_view_type = Some(view_type);

    if matches!(
        view_type,
        StreamViewType::NewImage | StreamViewType::NewAndOldImages
    ) && name != EventName::Remove
    {
        record.change.new_image = Some(item);
    }

    record
}

fn error_kind(err: &DecodeError) -> &'static str {
    match err {
        DecodeError::MissingNewImage { .. } => "missingNewImage",
        DecodeError::Record { .. } => "invalidRecord",
        _ => "other",
    }
}

fn event_cases() -> Vec<(&'static str, StreamRecord)> {
    let new = StreamViewType::NewImage;
    let opened = event_item(&event("acct-1", 1, "account:opened"), None).unwrap();
    let mut corrupt = event_item(&event("acct-1", 2, "account:deposited"), None).unwrap();
    corrupt.insert("metadata".into(), AttributeValue::S(String::new()));
    let snapshot = SerializedSnapshot {
        entity_id: "acct-1".into(),
        entity_type: "account".into(),
        sequence: EventSequence(1),
        event_sequence: EventSequence(1),
        payload: br#"{"balance":5}"#.to_vec(),
    };
    // The shape the commit path writes (`photon_evt::wire::dynamo::outcome_item`), at `sk = 1`.
    let outcome = Item::from([
        (
            "pk".into(),
            AttributeValue::S("command-outcome#cmd-0001".into()),
        ),
        ("sk".into(), AttributeValue::N("1".into())),
        ("status".into(), AttributeValue::S("accepted".into())),
        ("digest".into(), AttributeValue::S("sha256:00".into())),
        ("events".into(), AttributeValue::S(r#"["acct-1:1"]"#.into())),
    ]);

    vec![
        (
            "an inserted event",
            record(EventName::Insert, opened.clone(), "100", new),
        ),
        (
            "an inserted event, both images",
            record(
                EventName::Insert,
                opened.clone(),
                "101",
                StreamViewType::NewAndOldImages,
            ),
        ),
        (
            "a modified event item",
            record(EventName::Modify, opened.clone(), "102", new),
        ),
        (
            "a removed event item (compaction or TTL)",
            record(EventName::Remove, opened.clone(), "103", new),
        ),
        (
            "the stream head",
            record(
                EventName::Insert,
                head_item(&EntityId::new("acct-1"), EventSequence(1), None),
                "104",
                new,
            ),
        ),
        (
            "the inline snapshot",
            record(
                EventName::Insert,
                snapshot_item(&snapshot, None).unwrap(),
                "105",
                new,
            ),
        ),
        (
            "a command outcome",
            record(EventName::Insert, outcome, "106", new),
        ),
        (
            "an inserted event, keys only",
            record(EventName::Insert, opened, "107", StreamViewType::KeysOnly),
        ),
        (
            "an event item with empty metadata",
            record(EventName::Insert, corrupt, "108", new),
        ),
    ]
}

fn wakeup_cases() -> Vec<(&'static str, StreamRecord)> {
    let keys = StreamViewType::KeysOnly;
    let new = StreamViewType::NewImage;
    let row = view_row_item(
        &row_view(&scope("world:7"), 4, &event("acct-1", 1, "account:opened")).unwrap(),
    )
    .unwrap();
    let next = view_row_item(
        &row_view(
            &scope("world:7"),
            5,
            &event("acct-1", 2, "account:deposited"),
        )
        .unwrap(),
    )
    .unwrap();
    let place = view_row_item(
        &row_view(
            &scope("world:7/place:3"),
            1,
            &event("acct-1", 2, "account:deposited"),
        )
        .unwrap(),
    )
    .unwrap();
    let counter = view_row_item(&counter_view(&scope("world:7"), 12)).unwrap();
    let mut bad_row = row.clone();
    bad_row.insert("sk".into(), AttributeValue::S("4".into()));
    let other = view_row_item(&photon_evt::ViewRow::new(
        "account#acct-1",
        "VIEW",
        "acct-1",
        "account",
        br#"{"balance":5}"#.to_vec(),
    ))
    .unwrap();

    vec![
        (
            "a journal row, keys only",
            record(EventName::Insert, row.clone(), "200", keys),
        ),
        (
            "a journal row, new image",
            record(EventName::Insert, row.clone(), "201", new),
        ),
        (
            "a journal counter, keys only",
            record(EventName::Modify, counter.clone(), "202", keys),
        ),
        (
            "a journal counter, new image",
            record(EventName::Modify, counter.clone(), "203", new),
        ),
        (
            "a removed journal row (compaction)",
            record(EventName::Remove, row, "204", keys),
        ),
        (
            "another view row",
            record(EventName::Insert, other, "205", keys),
        ),
        (
            "a stray row in a journal partition (not a position)",
            record(EventName::Insert, bad_row, "206", keys),
        ),
        (
            "the next journal row of the scope",
            record(EventName::Insert, next, "207", keys),
        ),
        (
            "a journal row of another scope",
            record(EventName::Insert, place, "208", keys),
        ),
    ]
}

fn decoded_event(record: &StreamRecord) -> Value {
    match decode_event(record) {
        Ok(None) => json!({ "skip": true }),
        Ok(Some(streamed)) => json!({
            "event": serde_json::from_slice::<Value>(&streamed.event.to_json().unwrap()).unwrap(),
            "idempotencyKey": streamed.idempotency_key(),
        }),
        Err(err) => json!({ "error": error_kind(&err) }),
    }
}

fn wakeup_json(wakeup: &JournalWakeup) -> Value {
    json!({
        "scope": wakeup.scope.as_str(),
        "position": wakeup.position.map(|position| position.to_string()),
        "sequenceNumber": wakeup.sequence_number,
    })
}

fn decoded_wakeup(record: &StreamRecord) -> Value {
    match decode_wakeup(record) {
        None => json!({ "skip": true }),
        Some(wakeup) => json!({ "wakeup": wakeup_json(&wakeup) }),
    }
}

async fn batches() -> Value {
    let records = |cases: Vec<(&'static str, StreamRecord)>, take: &[usize]| StreamEvent {
        records: take.iter().map(|&index| cases[index].1.clone()).collect(),
    };

    // Events: the first succeeds, the head is skipped, the third fails in the handler.
    let mut deposit = event_cases()[0].1.clone();
    let item = event_item(&event("acct-1", 2, "account:deposited"), None).unwrap();
    deposit.change.keys = keys_of(&item);
    deposit.change.new_image = Some(item);
    deposit.change.sequence_number = "110".into();
    let mut events = records(event_cases(), &[0, 4]);
    events.records.push(deposit);

    let handler_fails = process_events(
        &events,
        &EventFilter::new(),
        async |streamed: StreamedEvent| {
            if streamed.event.event_type.as_str() == "account:deposited" {
                return Err::<(), BoxError>("unavailable".into());
            }

            Ok(())
        },
    )
    .await;
    let all_succeed = process_events(&events, &EventFilter::new(), async |_: StreamedEvent| {
        Ok::<(), BoxError>(())
    })
    .await;
    let corrupt = process_events(
        &records(event_cases(), &[0, 8, 1]),
        &EventFilter::new(),
        async |_: StreamedEvent| Ok::<(), BoxError>(()),
    )
    .await;

    let mut woken = Vec::new();
    let wakeups = records(wakeup_cases(), &[0, 5, 8, 2, 7, 3]);
    let coalesced = process_wakeups(
        &wakeups,
        &JournalFilter::rows(),
        async |wakeup: JournalWakeup| {
            woken.push(wakeup_json(&wakeup));
            Ok::<(), BoxError>(())
        },
    )
    .await;

    let response = |outcome: &photon_evt_lambda::BatchOutcome| {
        serde_json::to_value(outcome.response()).unwrap()
    };

    json!([
        {
            "name": "events: every record succeeds",
            "sequenceNumbers": events.records.iter().map(StreamRecord::sequence_number).collect::<Vec<_>>(),
            "response": response(&all_succeed),
        },
        {
            "name": "events: the handler fails on the third record",
            "sequenceNumbers": events.records.iter().map(StreamRecord::sequence_number).collect::<Vec<_>>(),
            "response": response(&handler_fails),
        },
        {
            "name": "events: the second record does not decode",
            "sequenceNumbers": ["100", "108", "101"],
            "response": response(&corrupt),
        },
        {
            "name": "journal rows: one wake-up per scope, the highest position",
            "sequenceNumbers": wakeups.records.iter().map(StreamRecord::sequence_number).collect::<Vec<_>>(),
            "wakeups": woken,
            "response": response(&coalesced),
        },
    ])
}

async fn generate() -> Value {
    let events: Vec<Value> = event_cases()
        .iter()
        .map(|(name, record)| {
            json!({
                "name": name,
                "record": serde_json::to_value(record).unwrap(),
                "decoded": decoded_event(record),
                "everyEventFilter": EventFilter::new().matches(record),
            })
        })
        .collect();
    let wakeups: Vec<Value> = wakeup_cases()
        .iter()
        .map(|(name, record)| {
            json!({
                "name": name,
                "record": serde_json::to_value(record).unwrap(),
                "decoded": decoded_wakeup(record),
                "rowsFilter": JournalFilter::rows().matches(record),
                "countersFilter": JournalFilter::counters().matches(record),
            })
        })
        .collect();

    json!({
        "filters": {
            "everyEvent": EventFilter::new().pattern().unwrap(),
            "accountEvents": EventFilter::new()
                .entity_type("account")
                .event_type("account:opened")
                .event_type_prefix("account:closed")
                .pattern()
                .unwrap(),
            "journalRows": JournalFilter::rows().pattern().unwrap(),
            "journalCounters": JournalFilter::counters().pattern().unwrap(),
            "journalScopes": JournalFilter::counters()
                .scope(&scope("world:7"))
                .scope_prefix("world:7/")
                .pattern()
                .unwrap(),
        },
        "events": events,
        "wakeups": wakeups,
        "batches": batches().await,
        "rowSortKey": row_sk(4),
        "emptyResponse": serde_json::to_value(BatchResponse::success()).unwrap(),
    })
}

#[tokio::test]
async fn the_lambda_fixture_matches_the_implementation() {
    let path = fixture_path();
    let generated = generate().await;

    if std::env::var_os("EVT_UPDATE_FIXTURES").is_some() {
        let mut text = serde_json::to_string_pretty(&generated).unwrap();
        text.push('\n');
        std::fs::write(&path, text).unwrap();

        return;
    }

    let stored: Value =
        serde_json::from_slice(&std::fs::read(&path).expect("read the lambda fixture")).unwrap();

    assert_eq!(
        stored, generated,
        "compat/fixtures/lambda.json is stale: regenerate it with EVT_UPDATE_FIXTURES=1"
    );
}

/// The stored records decode as the fixture says: the check a port starts from, reading the
/// fixture's record JSON rather than building records in code.
#[test]
fn the_fixture_records_decode_as_recorded() {
    let stored: Value =
        serde_json::from_slice(&std::fs::read(fixture_path()).expect("read the lambda fixture"))
            .unwrap();

    for case in stored["events"].as_array().unwrap() {
        let record: StreamRecord = serde_json::from_value(case["record"].clone()).unwrap();
        assert_eq!(decoded_event(&record), case["decoded"], "{}", case["name"]);
    }

    for case in stored["wakeups"].as_array().unwrap() {
        let record: StreamRecord = serde_json::from_value(case["record"].clone()).unwrap();
        assert_eq!(decoded_wakeup(&record), case["decoded"], "{}", case["name"]);
    }
}
